SELECT sec_code4, name, industry, current_price,
       ROUND(pbr, 2) AS pbr, ROUND(per, 1) AS per, ROUND(dividend_yield * 100, 2) AS dividend_yield_pct,
       ROUND(payout_ratio * 100, 0) AS payout_ratio_pct, market_cap_b
FROM m_screener
WHERE pbr > 0 AND pbr < {{max_pbr}}
  AND dividend_yield > {{min_yield_pct}} / 100
  AND market_cap_b >= {{min_mcap_oku}}
  AND (payout_ratio IS NULL OR payout_ratio <= {{max_payout_pct}} / 100)
ORDER BY dividend_yield DESC
LIMIT {{limit}}

SELECT sec_code4, name, industry, current_price,
       ROUND(roe * 100, 1) AS roe_pct, ROUND(per, 1) AS per, ROUND(pbr, 2) AS pbr,
       ROUND(operating_margin * 100, 1) AS operating_margin_pct, market_cap_b
FROM m_screener
WHERE roe >= {{min_roe_pct}} / 100 AND roe <= 1
  AND per > 0 AND per <= {{max_per}}
  AND market_cap_b >= {{min_mcap_oku}}
ORDER BY roe DESC
LIMIT {{limit}}

SELECT sec_code4, name, industry, market_cap_b,
       ROUND(net_cash_to_mcap * 100, 1) AS net_cash_to_mcap_pct, ROUND(pbr, 2) AS pbr, ROUND(per, 1) AS per,
       ROUND(equity_ratio * 100, 1) AS equity_ratio_pct, interest_bearing_debt_basis
FROM m_screener
WHERE net_cash_to_mcap >= {{min_ratio_pct}} / 100
  AND pbr > 0 AND pbr <= {{max_pbr}}
  AND market_cap_b >= {{min_mcap_oku}}
ORDER BY net_cash_to_mcap DESC
LIMIT {{limit}}

SELECT sec_code4, name, industry, ROUND(composite_score, 1) AS composite_score,
       ROUND(value_score, 1) AS value_score, ROUND(quality_score, 1) AS quality_score,
       ROUND(per, 1) AS per, ROUND(pbr, 2) AS pbr, ROUND(dividend_yield * 100, 2) AS dividend_yield_pct, market_cap_b
FROM m_screener
WHERE composite_score >= {{min_score}}
  AND market_cap_b >= {{min_mcap_oku}}
ORDER BY composite_score DESC
LIMIT {{limit}}
